import os
import codecs

from datetime import datetime, timedelta

from taf.rfrl.l3_call.logger.l3_call_logger import log_input_and_output, log_env_state, log_result
from taf.rfrl.l3_call.btslog.exceptions import AverageThroughputNotWithinDeviation, ThroughputMsgsNotFoundInBtslog


class BtsLog(object):
    __MISSING_IMPLEMENTATION_ERROR_MSG = "{} class has missing implementation of {} method"

    def __init__(self, duration, direction, throughput, deviation, cell_id, logfile_path):
        self._tput_variables = {}
        self._duration = duration
        self._direction = direction
        self._throughput = throughput
        self._deviation = deviation
        self._cell_id = cell_id
        self._logfile_path = logfile_path
        self._start_timestamp = None
        self._skip_timestamp_shift = False
        self._seconds_offset = 0
        self._update_timestamp()

    @log_input_and_output
    def verify_average_tput_using_btslog(self):
        """
        Checks whether the average throughput is within given deviation
        by parsing data transfer messages from btslog.

        :raises: AverageThroughputNotWithinDeviation when average
        throughput value is not within deviation limits

        :returns: average throughput
        :rtype: float
        """
        self._prepare_tput_variables(throughput=self._throughput, deviation=self._deviation)
        average_tput = self._calculate_average_tput_from_btslog(start_timestamp=self._start_timestamp,
                                                                duration=self._duration,
                                                                direction=self._direction)

        self._verify_average_tput(average_tput=average_tput)

        return average_tput

    def _update_timestamp(self):
        logfiles = self._get_all_btslog_files()
        latest_logfile = max(logfiles, key=os.path.getctime)
        num_newlines = 0

        with open(latest_logfile, 'rb') as f:
            try:
                f.seek(-2, os.SEEK_END)
                while num_newlines < 2:
                    f.seek(-2, os.SEEK_CUR)
                    if f.read(1) == b'\n':
                        num_newlines += 1
            except OSError:
                f.seek(0)
            last_line = f.readline().decode()

        self._start_timestamp = last_line.split(" ")[2]

    def _prepare_tput_variables(self, throughput, deviation):
        self._tput_variables["target_tput"] = float(throughput.strip("Mbits/sec"))
        self._tput_variables["deviation"] = float(deviation.strip("%")) / 100

        tput_times_deviation = self._tput_variables["target_tput"] * self._tput_variables["deviation"]

        self._tput_variables["lower_limit"] = self._tput_variables["target_tput"] - tput_times_deviation
        self._tput_variables["upper_limit"] = self._tput_variables["target_tput"] + tput_times_deviation

    def _calculate_average_tput_from_btslog(self, start_timestamp, duration, direction):
        delta_seconds = int(duration.strip("s")) * 0.9
        start_timestamp = datetime.strptime(start_timestamp, "%H:%M:%S.%f")
        stop_timestamp = start_timestamp + timedelta(seconds=delta_seconds * 0.9)

        tputs = self._get_tput_values_and_convert_to_megabits(start_timestamp=start_timestamp,
                                                              stop_timestamp=stop_timestamp,
                                                              direction=direction)
        average_tput = sum(tputs) / len(tputs)
        return average_tput

    def _verify_average_tput(self, average_tput):
        if not self._tput_variables["lower_limit"] <= average_tput <= self._tput_variables["upper_limit"]:
            raise AverageThroughputNotWithinDeviation(
                "Average throughput value {:.2f} Mbist/sec not within deviation limits: {:.2f}"
                " Mbits/sec >= {:.2f} Mbits/sec <= {:.2f} Mbits/sec".format(
                    average_tput, self._tput_variables["lower_limit"], self._tput_variables["target_tput"],
                    self._tput_variables["upper_limit"]
                )
            )

    @log_input_and_output
    def _get_tput_values_and_convert_to_megabits(self, start_timestamp, stop_timestamp, direction):
        tput_values_in_bytes = self._parse_tput_msgs_from_btslog(start_timestamp=start_timestamp,
                                                                 stop_timestamp=stop_timestamp,
                                                                 direction=direction)
        tput_values_in_megabits = [tput * 7.6294 * 10**-6 for tput in tput_values_in_bytes]

        log_env_state("throughput values in megabits: {}".format(tput_values_in_megabits))

        return tput_values_in_megabits

    def _parse_tput_msgs_from_btslog(self, start_timestamp, stop_timestamp, direction):
        logfiles = self._get_all_btslog_files()

        tput_values = []
        tput_lines = []
        for logfile in logfiles:
            self._parse_tput_values(btslog_path=logfile,
                                    start_timestamp=start_timestamp,
                                    stop_timestamp=stop_timestamp,
                                    direction=direction,
                                    tput_values=tput_values,
                                    tput_lines=tput_lines)
        self._save_tput_lines_to_file(tput_lines, direction)
        if not tput_values:
            raise ThroughputMsgsNotFoundInBtslog(f"No proper messages concerning data transfer found in btslog for "
                                                 f"CELLID: {self._cell_id}! Check whether your swconfig is correct and "
                                                 f"that btslog collection was started properly.")
        return tput_values

    def _parse_tput_values(self, btslog_path, start_timestamp, stop_timestamp, direction, tput_values, tput_lines):
        with codecs.open(btslog_path, "r", encoding='utf-8', errors='ignore') as log_file:
            for line in log_file.readlines():
                if direction.lower() == "dl":
                    tput_value = self._parse_dl_tput_value(line=line, start_timestamp=start_timestamp,
                                                           stop_timestamp=stop_timestamp)

                if direction.lower() == "ul":
                    tput_value = self._parse_ul_tput_value(line=line, start_timestamp=start_timestamp,
                                                           stop_timestamp=stop_timestamp)

                if tput_value is not None and (self._skip_timestamp_shift or tput_value != 0):
                    tput_values.append(tput_value)
                    tput_lines.append(line)
                if tput_value == 0:
                    start_timestamp = self._shift_start_timestamp(start_timestamp, self._seconds_offset)

    def _parse_dl_tput_value(self, line, start_timestamp, stop_timestamp):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._parse_dl_tput_value.__name__))

    def _parse_ul_tput_value(self, line, start_timestamp, stop_timestamp):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._parse_ul_tput_value.__name__))

    @log_input_and_output
    def _get_all_btslog_files(self):
        btslog_path = "/tmp/btslog2/"
        logfiles = [
            btslog_path + logfile
            for logfile in os.listdir(btslog_path)
            if logfile.startswith("SYSLOG_")
        ]

        return logfiles

    def _shift_start_timestamp(self, start_timestamp, seconds_to_add):
        if not self._skip_timestamp_shift:
            start_timestamp += timedelta(seconds=seconds_to_add)
            log_result(f"Shifting timestamp by {seconds_to_add}s. New timestamp: {start_timestamp}")

        self._skip_timestamp_shift = True
        return start_timestamp

    def _save_tput_lines_to_file(self, tput_msgs, direction):
        with open(self._logfile_path, 'a') as f:
            f.write(f"{direction.upper()}{'-'*300}\n")
            for tput_msg in tput_msgs:
                f.write(f"{tput_msg}")
        log_result(f"Saved btslog tput prints to: {self._logfile_path}")
